//! Artifact storage.
//!
//! Artifacts (screenshots, videos, traces, logs) are stored under opaque keys of the
//! form `<workspace>/<project>/<execution>/<job>/<file>`. The key is generated by the
//! server; user-supplied names are sanitised so they can never escape the root.

use async_trait::async_trait;
use sha2::{Digest, Sha256};
use std::path::{Component, Path, PathBuf};

#[derive(Debug, thiserror::Error)]
pub enum ArtifactError {
    #[error("artifact not found")]
    NotFound,
    #[error("invalid artifact key")]
    InvalidKey,
    #[error("artifact too large ({0} bytes)")]
    TooLarge(usize),
    #[error("storage io: {0}")]
    Io(#[from] std::io::Error),
}

#[derive(Debug, Clone)]
pub struct StoredArtifact {
    pub key: String,
    pub size_bytes: u64,
    pub sha256: String,
}

#[async_trait]
pub trait ArtifactStore: Send + Sync {
    async fn put(&self, key: &str, bytes: &[u8]) -> Result<StoredArtifact, ArtifactError>;
    async fn get(&self, key: &str) -> Result<Vec<u8>, ArtifactError>;
    async fn delete(&self, key: &str) -> Result<(), ArtifactError>;
    fn backend(&self) -> &'static str;
}

/// Sanitise a client-supplied file name to `[A-Za-z0-9._-]`, max 120 chars.
pub fn sanitize_name(name: &str) -> String {
    let cleaned: String = name
        .chars()
        .map(|c| {
            if c.is_ascii_alphanumeric() || matches!(c, '.' | '-' | '_') {
                c
            } else {
                '_'
            }
        })
        .collect();
    let trimmed = cleaned.trim_start_matches('.');
    let mut s: String = trimmed.chars().take(120).collect();
    if s.is_empty() {
        s = "artifact".into();
    }
    s
}

/// Validate a storage key: relative, no `..`, no absolute components.
fn checked_relative(key: &str) -> Result<PathBuf, ArtifactError> {
    let p = Path::new(key);
    if key.is_empty() || p.is_absolute() {
        return Err(ArtifactError::InvalidKey);
    }
    for c in p.components() {
        match c {
            Component::Normal(_) => {}
            _ => return Err(ArtifactError::InvalidKey),
        }
    }
    Ok(p.to_path_buf())
}

pub struct LocalArtifactStore {
    root: PathBuf,
    max_bytes: usize,
}

impl LocalArtifactStore {
    pub fn new(root: impl Into<PathBuf>, max_bytes: usize) -> Self {
        Self {
            root: root.into(),
            max_bytes,
        }
    }
}

#[async_trait]
impl ArtifactStore for LocalArtifactStore {
    async fn put(&self, key: &str, bytes: &[u8]) -> Result<StoredArtifact, ArtifactError> {
        if bytes.len() > self.max_bytes {
            return Err(ArtifactError::TooLarge(bytes.len()));
        }
        let rel = checked_relative(key)?;
        let path = self.root.join(rel);
        if let Some(parent) = path.parent() {
            tokio::fs::create_dir_all(parent).await?;
        }
        let tmp = path.with_extension(format!("tmp-{}", uuid::Uuid::new_v4()));
        tokio::fs::write(&tmp, bytes).await?;
        tokio::fs::rename(&tmp, &path).await?;
        Ok(StoredArtifact {
            key: key.to_string(),
            size_bytes: bytes.len() as u64,
            sha256: hex::encode(Sha256::digest(bytes)),
        })
    }

    async fn get(&self, key: &str) -> Result<Vec<u8>, ArtifactError> {
        let path = self.root.join(checked_relative(key)?);
        match tokio::fs::read(&path).await {
            Ok(b) => Ok(b),
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => Err(ArtifactError::NotFound),
            Err(e) => Err(e.into()),
        }
    }

    async fn delete(&self, key: &str) -> Result<(), ArtifactError> {
        let path = self.root.join(checked_relative(key)?);
        match tokio::fs::remove_file(&path).await {
            Ok(()) => Ok(()),
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(()),
            Err(e) => Err(e.into()),
        }
    }

    fn backend(&self) -> &'static str {
        "local"
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn sanitizes() {
        assert_eq!(sanitize_name("../../etc/passwd"), "_.._etc_passwd");
        assert_eq!(sanitize_name("shot 1.png"), "shot_1.png");
        assert_eq!(sanitize_name(""), "artifact");
        assert!(checked_relative("../x").is_err());
        assert!(checked_relative("/abs").is_err());
        assert!(checked_relative("a/b/c.png").is_ok());
    }

    #[tokio::test]
    async fn local_roundtrip() {
        let dir = tempfile::tempdir().unwrap();
        let store = LocalArtifactStore::new(dir.path(), 1024);
        let s = store.put("w/p/e/j/a.txt", b"hello").await.unwrap();
        assert_eq!(s.size_bytes, 5);
        assert_eq!(store.get("w/p/e/j/a.txt").await.unwrap(), b"hello");
        assert!(matches!(
            store.put("x", &[0u8; 2048]).await,
            Err(ArtifactError::TooLarge(_))
        ));
        assert!(matches!(
            store.get("nope").await,
            Err(ArtifactError::NotFound)
        ));
        store.delete("w/p/e/j/a.txt").await.unwrap();
        assert!(store.get("w/p/e/j/a.txt").await.is_err());
    }
}
